<?php if ( ! defined( 'ABSPATH' ) ) { exit; } get_header(); $selected_category=isset($_GET['category'])?sanitize_text_field(wp_unslash($_GET['category'])):''; $categories=get_terms(array('taxonomy'=>'nvconsult_article_category','hide_empty'=>true)); ?>
<main class="archive-shell"><section class="archive-hero"><h1><?php post_type_archive_title(); ?></h1><p><?php esc_html_e( 'Guides, updates, and insights for your global journey.', 'nvconsult-theme-v2' ); ?></p></section><section class="section" style="padding-top:24px;"><form class="filter-bar" method="get"><select name="category"><option value=""><?php esc_html_e( 'All categories', 'nvconsult-theme-v2' ); ?></option><?php foreach($categories as $category): ?><option value="<?php echo esc_attr( $category->slug ); ?>" <?php selected($selected_category,$category->slug); ?>><?php echo esc_html( $category->name ); ?></option><?php endforeach; ?></select><button class="btn-primary" type="submit"><?php esc_html_e( 'Filter Articles', 'nvconsult-theme-v2' ); ?></button></form><div class="archive-grid"><?php if(have_posts()): while(have_posts()): the_post(); if($selected_category&&!has_term($selected_category,'nvconsult_article_category',get_the_ID())){continue;} ?><article class="archive-card content-card"><?php if(has_post_thumbnail()): the_post_thumbnail('large'); endif; ?><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p class="entry-meta"><?php echo esc_html( get_the_date() ); ?></p><p><?php echo esc_html( wp_trim_words( get_the_excerpt(), 24 ) ); ?></p></article><?php endwhile; else: ?><div class="placeholder-message"><p><?php esc_html_e( 'No articles found yet.', 'nvconsult-theme-v2' ); ?></p></div><?php endif; ?></div></section></main>
<?php get_footer(); ?>
